// Keep upright reading surfaces parallel to the image plane. Lens shift
// provides headroom without tilting the camera towards the top of the text.
export function exhibitionFramedView(view) {
  const eye=[...view.eye],target=[...view.target];
  const distance=Math.hypot(target[0]-eye[0],target[2]-eye[2]);
  const lift=view.flat&&distance>0?(target[1]-eye[1])/distance:0;
  if(view.flat)target[1]=eye[1];
  return {eye,target,lift};
}

export function exhibitionLensShift(lift, fov) {
  return -lift/(2*Math.tan(fov*Math.PI/360));
}

export function exhibitionReadingFrameLift(lift, progress = 0) {
  const t = Math.max(0, Math.min(1, progress));
  const eased = t * t * t * (t * (t * 6 - 15) + 10);
  return lift * (1 - eased);
}

// Bring height, pitch and lens shift into the final composition together.
// The first part of the approach establishes direction. A quintic curve then
// accelerates gently and finishes with zero velocity and acceleration.
export function exhibitionApproachFrame(from, to, progress) {
  const t = Math.max(0, Math.min(1, (progress - .15) / .85));
  const blend = t * t * t * (t * (t * 6 - 15) + 10);
  return Object.fromEntries(['height', 'pitch', 'lift'].map(key => [key, from[key] + (to[key] - from[key]) * blend]));
}
